previewCss:
.darma-loader-swing-set {
  position: relative;
  width: 48px;
  height: 52px;
}
.darma-loader-swing-set::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 4px;
  right: 4px;
  height: 3px;
  border-radius: 2px;
  background: #4338ca;
}
.darma-loader-swing-set i {
  position: absolute;
  top: 8px;
  left: 50%;
  width: 20px;
  height: 30px;
  margin-left: -10px;
  transform-origin: top center;
  animation: darma-loader-swing-set-sw 1.6s ease-in-out infinite;
}
.darma-loader-swing-set i::before {
  content: "";
  position: absolute;
  top: 0;
  left: 2px;
  width: 2px;
  height: 26px;
  background: #c7d2fe;
  box-shadow: 14px 0 0 #c7d2fe;
}
.darma-loader-swing-set i::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 20px;
  height: 5px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
}
@keyframes darma-loader-swing-set-sw {
  0%, 100% { transform: rotate(-20deg); }
  50% { transform: rotate(20deg); }
}

